			Map<String, Map<String, String>> original = fixture.image();
			assertThat(original.get("retired_ids")).hasSize(1);
			assertThat(original.get("retired_ids_seq")).hasSize(1);
			assertThat(original.get("gc_meta")).hasSize(3);
			assertRejected(fixture, ownership, epoch, original);

			fixture.replaceEpoch(Long.MAX_VALUE - 1L);
			Map<String, Map<String, String>> beforeLastAdvance = fixture.image();
			Map<String, Map<String, String>> atMaximum = withEpoch(beforeLastAdvance, Long.MAX_VALUE);
			assertLastLegalAdvance(fixture, ownership, atMaximum);
			assertRejected(fixture, ownership, Long.MAX_VALUE, atMaximum);
